-- Academy: rebuild Yachts Module 2 as "Meet the Yacht": 20 pages (11 with quick checks, 9 with answerable exercises
-- saved to the Broker Portfolio) + a 7-question final quiz. Same shape as the Module 1 migration.

do $mig$
declare
  v_module uuid;
  v_q uuid;
  v_page uuid;
  rec jsonb;
  n int := 0;
  i int;
  v_pages jsonb := $json$[{"heading": "Meet the Yacht: Do I Actually Find Yachts Interesting?", "body": "<p><b>Before we begin</b></p><p>You have now stepped into the yacht world.</p><p>You know that brokerage is one part of a much larger industry, and that the job involves far more than selling a beautiful object.</p><p>Now we turn to the object itself.</p><p><b>The yacht.</b></p><p>This is where your education becomes more visual, physical and specific.</p><p>You are not expected to become a naval architect, engineer or captain.</p><p>Your objective is simpler:</p><p><em>Learn to look at a yacht intelligently.</em></p><p>When an experienced broker steps aboard, they don't simply see polished surfaces and expensive furniture. They start asking:</p><p>&bull; What was this yacht designed to do?<br/>&bull; How will people actually use it?<br/>&bull; Who is it suited to?<br/>&bull; Where are its strengths?<br/>&bull; Where are its compromises?<br/>&bull; What does the specification tell us?<br/>&bull; What still needs to be investigated?</p><p>That is the beginning of professional product knowledge.</p>", "q": "What is the objective of this module?", "opts": ["Become a naval architect", "Learn to look at a yacht intelligently", "Memorise every yacht builder", "Learn to operate a yacht's bridge"], "correct": 1}, {"heading": "Chapter 1: The Main Types of Yachts", "body": "<p><b>One word. Many worlds.</b></p><p>Imagine someone tells you:</p><p><em>\"I'm looking for a yacht.\"</em></p><p>That sentence tells you almost nothing. It is like saying \"I'm looking for a house.\" For whom? Where? For what purpose? How often will it be used?</p><p>Before recommending anything, you need to understand what kind of yacht the client actually needs.</p><p><b>Motor yachts</b></p><p>Motor yachts are powered primarily by engines and represent a major part of the brokerage market. But within that category are very different design philosophies. A yacht may prioritise speed, range, comfort, entertainment, family use, exploration, privacy, interior volume or outdoor living.</p><p>Two motor yachts of the same length can therefore offer completely different experiences.</p><p><b>Fast motor yachts</b></p><p>Designed around performance: powerful engines, high cruising speeds, sleek hull forms, sporty styling and large exterior areas.</p><p>For a client wanting rapid transfers between destinations, performance may be fundamental. For a client who spends most of the time at anchor, space, stability and outdoor living may matter much more.</p><p><b>Displacement yachts</b></p><p>Some larger motor yachts prioritise efficiency, range and comfortable cruising rather than maximum speed. They may offer long range, substantial volume, efficient operation and strong long-distance capability, which makes them relevant to clients planning extended passages.</p><p><b>Explorer yachts</b></p><p>Designed with demanding cruising environments in mind. They may emphasise long range, autonomy, robust construction, storage, technical capacity, tenders and equipment, and expedition capability.</p><p>For a client dreaming of remote destinations, these characteristics may be central to the purchase.</p><p><b>Sportfishers</b></p><p>Designed around fishing activity: large aft working areas, specialised storage, fishing equipment, cockpit space and long-range capability.</p><p>A fishing enthusiast may place enormous value on features another buyer barely notices.</p>", "q": "A prospective client says, \"I'm looking for a yacht.\" What does that tell you?", "opts": ["Almost nothing. You need to understand what kind of yacht they actually need", "Enough to start proposing vessels", "That they want a motor yacht", "That they want the largest yacht their budget allows"], "correct": 0}, {"heading": "Chapter 1 (continued): Sail, Catamarans, Classics and the Big Shift", "body": "<p><b>Sailing yachts</b></p><p>Sailing yachts introduce a different relationship with the water. Their design is influenced by sails, rig, hull design, draft, sailing performance, cockpit configuration, stability and handling.</p><p>Some prioritise cruising and comfort. Others prioritise performance. Others combine sailing capability with high levels of luxury.</p><p><b>Catamarans</b></p><p>Catamarans have two hulls rather than one. Depending on the design, this can provide substantial interior volume, large deck areas, stability, shallow draft and strong indoor/outdoor connections.</p><p>They are particularly prominent in some charter markets and can appeal to clients who prioritise space and stability.</p><p><b>Classic yachts</b></p><p>Some clients are drawn to yachts because of heritage rather than purely modern functionality. A classic yacht may offer historical significance, traditional craftsmanship, distinctive design, important pedigree and unique character.</p><p>That character can be a major part of the appeal, while also bringing specialised maintenance considerations.</p><p><b>The important shift</b></p><p>Don't try to memorise every yacht category. Instead, start with three questions:</p><p>&bull; What is this yacht designed to do?<br/>&bull; Where is it intended to operate?<br/>&bull; Who is most likely to value those characteristics?</p><p>That gives you a much stronger foundation than simply memorising names.</p><p><b>Yacht type snapshot</b></p><p>&bull; Fast motor yacht: performance and speed<br/>&bull; Displacement yacht: range, comfort, efficiency<br/>&bull; Explorer yacht: long-range, remote cruising<br/>&bull; Sportfisher: fishing and offshore activity<br/>&bull; Sailing yacht: sailing, lifestyle, performance<br/>&bull; Catamaran: space, stability, shallow draft<br/>&bull; Classic yacht: heritage, character, craftsmanship</p><p>These are broad categories, not rules. A yacht can cross several.</p>", "q": "Rather than memorising yacht categories, which three questions give you a stronger foundation?", "opts": ["How old is it, how long is it, and how much does it cost?", "Who built it, who owns it, and who crews it?", "What is it designed to do, where is it intended to operate, and who is most likely to value those characteristics?", "What colour is it, what does it cost, and how fast is it?"], "correct": 2}, {"heading": "Exercise: Yacht Type Detective", "body": "<p><b>Yacht Type Detective</b></p><p>Choose <b>three real yachts</b> from listings. Keep your reasoning short. You will revisit these yachts later in the module.</p><p>For each, you will record the yacht type, approximate length, apparent intended use, one feature that supports that use, and one question you would want answered. Then finish with one sentence: <em>\"I think this yacht was designed for...\"</em></p><p>Your answers are saved to your Broker Portfolio.</p>", "exercise": {"intro": "Pick three real yachts from listings. Keep your reasoning short, and remember them: you will use the first one again in the next exercises.", "groups": [{"title": "Yacht 1", "section": "yachts", "fields": [{"key": "y1_name", "label": "Yacht 1: name or listing", "type": "short", "min": 3, "placeholder": "Name, builder or listing link"}, {"key": "y1_type", "label": "Yacht 1: yacht type", "type": "short", "min": 3}, {"key": "y1_length", "label": "Yacht 1: approximate length", "type": "short", "min": 2, "placeholder": "e.g. 38m"}, {"key": "y1_use", "label": "Yacht 1: apparent intended use", "type": "short", "min": 5}, {"key": "y1_feature", "label": "Yacht 1: one feature that supports that use", "type": "short", "min": 5}, {"key": "y1_question", "label": "Yacht 1: one question you would want answered", "type": "short", "min": 8}, {"key": "y1_designed", "label": "I think this yacht was designed for...", "type": "long", "min": 15}]}, {"title": "Yacht 2", "section": "yachts", "fields": [{"key": "y2_name", "label": "Yacht 2: name or listing", "type": "short", "min": 3, "placeholder": "Name, builder or listing link"}, {"key": "y2_type", "label": "Yacht 2: yacht type", "type": "short", "min": 3}, {"key": "y2_length", "label": "Yacht 2: approximate length", "type": "short", "min": 2, "placeholder": "e.g. 38m"}, {"key": "y2_use", "label": "Yacht 2: apparent intended use", "type": "short", "min": 5}, {"key": "y2_feature", "label": "Yacht 2: one feature that supports that use", "type": "short", "min": 5}, {"key": "y2_question", "label": "Yacht 2: one question you would want answered", "type": "short", "min": 8}, {"key": "y2_designed", "label": "I think this yacht was designed for...", "type": "long", "min": 15}]}, {"title": "Yacht 3", "section": "yachts", "fields": [{"key": "y3_name", "label": "Yacht 3: name or listing", "type": "short", "min": 3, "placeholder": "Name, builder or listing link"}, {"key": "y3_type", "label": "Yacht 3: yacht type", "type": "short", "min": 3}, {"key": "y3_length", "label": "Yacht 3: approximate length", "type": "short", "min": 2, "placeholder": "e.g. 38m"}, {"key": "y3_use", "label": "Yacht 3: apparent intended use", "type": "short", "min": 5}, {"key": "y3_feature", "label": "Yacht 3: one feature that supports that use", "type": "short", "min": 5}, {"key": "y3_question", "label": "Yacht 3: one question you would want answered", "type": "short", "min": 8}, {"key": "y3_designed", "label": "I think this yacht was designed for...", "type": "long", "min": 15}]}]}}, {"heading": "Chapter 2: Walk Around a Yacht", "body": "<p><b>Learning to see</b></p><p>Now take one of your three yachts. Before reading its specifications, look at the photographs as if you have never seen it before. Your objective is to build an observation habit.</p><p><b>Start with the profile</b></p><p>Look at the yacht from the side. Notice length, height, number of decks, bow and stern shape, window arrangement, exterior spaces, balconies, mast or radar equipment, tenders and the swimming platform.</p><p>Ask: <em>What does this exterior suggest about how the yacht is intended to be used?</em></p><p><b>The bow</b></p><p>The forward end. Depending on the yacht, this area may provide sunbathing, seating, storage, mooring equipment or anchor equipment. Some yachts make the bow a major guest area; others use it primarily for operations.</p><p><b>The aft deck</b></p><p>Often an important social space: dining, lounging, breakfast, entertaining, shade and access to the water. Look at its size and relationship to the interior, then imagine it being used by a full group of guests.</p><p><b>The swim platform</b></p><p>It can influence the entire experience of a yacht: water access, tender boarding, water-sports access, sunbathing and easier family access to the sea. For a water-focused client this may be important. For another, much less so.</p><p><b>Other features to identify</b></p><p>Try to locate the bridge or wheelhouse, side decks, foredeck, flybridge, passerelle, tender garage, beach club, anchor and mooring equipment, and superstructure. You don't need to know everything about each yet. Start by recognising what you are looking at.</p><p><b>The bridge</b></p><p>The yacht's navigation and command centre. It may contain navigation equipment, radar, communications, steering controls, electronic chart systems and monitoring systems. You don't need to operate it. You need to know what it is and why it matters.</p><p><b>The engine room</b></p><p>Where the yacht's mechanical and support systems come together: main engines, generators, pumps, electrical, fuel and water systems, air-conditioning and filtration. It is one of the first places where you see the difference between the yacht as a luxury environment and the yacht as a complex machine.</p><p><b>A word of caution</b></p><p>You can observe cleanliness, organisation, accessibility, apparent presentation and labelling. You cannot determine mechanical condition simply by looking. That requires appropriate technical expertise and inspection.</p><p>A broker needs to know the difference between <b>observing a condition</b> and <b>certifying a condition</b>.</p>", "q": "What is the difference between observing a condition and certifying it?", "opts": ["There is no real difference", "You can certify mechanical condition by studying photographs closely", "Certifying is only needed for older yachts", "Observing notes what you can see; certifying requires appropriate technical expertise and inspection"], "correct": 3}, {"heading": "Exercise: The Five-Minute Yacht Walk", "body": "<p><b>The Five-Minute Yacht Walk</b></p><p>Use the same yacht as your first pick in the Yacht Type Detective exercise. Give yourself five minutes.</p><p>Without reading the listing, write what you can see, what you think it tells you, and what you cannot know from photographs. Then reveal the listing and compare.</p><p>This is your first exercise in separating <b>observation from verification</b>.</p>", "exercise": {"intro": "Use your first yacht. Do the first three boxes before you read the listing, then open the listing and complete the last three.", "groups": [{"title": "Before the listing", "section": "yachts", "fields": [{"key": "w_yacht", "label": "Which yacht are you using?", "type": "short", "min": 3}, {"key": "w_see", "label": "What I can see", "type": "long", "min": 25}, {"key": "w_tells", "label": "What I think it tells me", "type": "long", "min": 25}, {"key": "w_cannot", "label": "What I cannot know from photographs", "type": "long", "min": 20}]}, {"title": "After the listing", "section": "yachts", "fields": [{"key": "w_right", "label": "What did you observe correctly?", "type": "long", "min": 15}, {"key": "w_wrong", "label": "What did you assume incorrectly?", "type": "long", "min": 15}, {"key": "w_next", "label": "What would you investigate next?", "type": "long", "min": 15}]}]}}, {"heading": "Chapter 3: Step Inside", "body": "<p><b>The yacht becomes a lifestyle</b></p><p>A yacht interior is not simply a collection of expensive rooms. It is a system designed around <b>people + movement + privacy + service + living.</b></p><p><b>The owner's suite</b></p><p>Look beyond the bed. Consider privacy, views, natural light, exterior access, storage, bathroom, dressing area and overall space. Then ask: <em>Would this work for the owner I have in mind?</em></p><p><b>Guest cabins</b></p><p>Look at number, configuration, size, privacy, location, accessibility and convertible arrangements. Ten guests can be accommodated in very different ways. The number alone tells you little about the experience.</p><p><b>The main saloon</b></p><p>Look at seating, dining, entertainment, circulation, windows and the relationship with outdoor areas. Ask: can people relax, dine and move through this space comfortably at the same time?</p><p><b>The galley</b></p><p>A working environment. Consider location, storage, service routes, connection to dining, crew access and separation from guests. You don't need to assess it technically. You are learning to see how the yacht operates.</p><p><b>Crew areas</b></p><p>Crew need cabins, mess areas, storage, working spaces, access routes and technical support. A yacht can look extraordinary from the guest areas while presenting a very different operational picture behind the scenes. That is why you need to look at both sides.</p><p><b>Guest flow and crew flow</b></p><p>Imagine an evening onboard. Guests are dining. Crew are serving. Food moves from the galley to the table. Used plates disappear. Drinks arrive.</p><p>The guest should experience the evening, not the logistics behind it. Good yacht design helps make that possible. This is <b>flow</b>.</p><p><b>Privacy</b></p><p>Luxury is partly about having control over interaction. A well-designed yacht may allow guests to socialise, owners to retreat, children to have their own space and crew to work discreetly.</p>", "q": "What does \"flow\" mean in yacht design?", "opts": ["How fast water moves past the hull", "Guests and crew can move and work without the guest experience being interrupted by the logistics behind it", "The number of decks on a yacht", "How quickly a yacht can be refuelled"], "correct": 1}, {"heading": "Exercise: Trace the Flow", "body": "<p><b>Trace the Flow</b></p><p>Using the same yacht, mark its basic layout and trace two journeys.</p><p><b>Guest:</b> cabin, breakfast, swimming, lunch, lounge, dinner.</p><p><b>Crew:</b> crew area, galley, dining, service, clean-up, crew area.</p><p>You are not designing the yacht. You are learning to read it.</p>", "exercise": {"intro": "Use the same yacht. Describe each journey through the layout in your own words.", "groups": [{"title": "Two journeys", "section": "yachts", "fields": [{"key": "f_guest", "label": "Guest journey: cabin → breakfast → swimming → lunch → lounge → dinner", "type": "long", "min": 40}, {"key": "f_crew", "label": "Crew journey: crew area → galley → dining → service → clean-up → crew area", "type": "long", "min": 40}]}, {"title": "What the layout tells me", "section": "yachts", "fields": [{"key": "f_good", "label": "One area where the layout appears particularly effective", "type": "long", "min": 20}, {"key": "f_investigate", "label": "One area you would want to investigate", "type": "long", "min": 20}]}]}}, {"heading": "Chapter 4: What's Underneath?", "body": "<p><b>The yacht is a machine</b></p><p>A yacht is simultaneously a luxury environment, a transport platform, a complex machine, a workplace and an asset. Now we look at the systems that make the experience possible.</p><p><b>Propulsion</b></p><p>The propulsion system moves the yacht. Motor yachts can use different configurations, but at a basic level think: <b>engine → propulsion system → movement.</b> Then connect that to speed, range, fuel consumption and operating conditions.</p><p><b>Cruising speed vs maximum speed</b></p><p>A yacht advertised at 25 knots does not necessarily spend its life travelling at 25 knots.</p><p><b>Cruising speed</b> is generally more relevant to routine operation. <b>Maximum speed</b> describes the upper end of published performance under stated conditions.</p><p>The difference matters because operating speed can affect fuel consumption, range, comfort and engine loading.</p><p><b>Range</b></p><p>Range indicates how far a yacht can travel under stated assumptions before refuelling. Those assumptions matter. Range can vary with speed, sea conditions, load, fuel capacity and operating conditions.</p><p>Treat range as a specification to understand, not a promise without context.</p><p><b>Draft</b></p><p>The distance from the waterline to the deepest part of the vessel below the water. It can affect access to shallow waters. For a client dreaming of shallow anchorages, draft can become an important consideration.</p><p><b>Beam</b></p><p>The width of the yacht. It can contribute to interior volume, stability, spaciousness and exterior living areas. It can also influence marina and access considerations.</p>", "q": "Why is cruising speed generally more relevant than maximum speed?", "opts": ["Maximum speed is never published accurately", "Cruising speed is always higher", "It reflects routine operation, and affects fuel consumption, range and comfort", "Maximum speed only matters for sailing yachts"], "correct": 2}, {"heading": "Chapter 4 (continued): Size, Fuel and Comfort", "body": "<p><b>Gross tonnage</b></p><p><b>GT</b> measures enclosed vessel volume. It does <b>not</b> mean weight.</p><p>This is important because two yachts of identical length can have dramatically different amounts of usable volume. Start breaking the habit of thinking: <em>length = size.</em> It doesn't.</p><p><b>Displacement</b></p><p>Displacement relates to the vessel's mass through the amount of water it displaces. For now, remember the distinction:</p><p>&bull; Length: one dimension<br/>&bull; Beam: width<br/>&bull; GT: enclosed volume<br/>&bull; Displacement: mass</p><p>They describe different things.</p><p><b>Fuel and water</b></p><p>Fuel capacity influences range, operating flexibility and logistics. Freshwater capacity and production affect how a yacht supports guests and crew. Systems such as watermakers can produce fresh water onboard, but capacity and production still matter.</p><p>These are examples of the invisible infrastructure behind the luxury experience.</p><p><b>Stabilisation</b></p><p>Some yachts use stabilisation systems to reduce vessel movement. At beginner level, understand the objective: <b>improve comfort by reducing motion.</b> The technology itself can be studied later.</p>", "q": "Two 40m yachts have a GT of 320 and 470. What does that difference most likely suggest?", "opts": ["Different amounts of enclosed, usable volume", "The larger GT yacht is heavier by exactly that difference", "The larger GT yacht is faster", "The smaller GT yacht is older"], "correct": 0}, {"heading": "Exercise: The Engine Room", "body": "<p><b>The engine room exercise</b></p><p>Compare photographs of two yacht engine rooms. Don't try to identify every component.</p><p>Instead note organisation, accessibility, cleanliness, space, labelling and apparent complexity. Then answer: <em>what would I want an engineer to explain to me?</em></p><p>The objective is not technical expertise. It is knowing what you don't yet know.</p>", "exercise": {"intro": "Find photographs of two yacht engine rooms (listings, builder brochures or refit galleries work well) and compare them.", "groups": [{"title": "Two engine rooms", "section": "yachts", "fields": [{"key": "e_a", "label": "Engine room 1: what I noticed (organisation, accessibility, cleanliness, space, labelling, apparent complexity)", "type": "long", "min": 30}, {"key": "e_b", "label": "Engine room 2: what I noticed", "type": "long", "min": 30}, {"key": "e_diff", "label": "What differs most between the two, and what might that suggest?", "type": "long", "min": 25}]}, {"title": "What I don't yet know", "section": "yachts", "fields": [{"key": "e_ask", "label": "What would I want an engineer to explain to me?", "type": "long", "min": 30}]}]}}, {"heading": "Chapter 5: Understanding the Numbers", "body": "<p><b>Specifications are not decoration</b></p><p>Yacht listings contain numbers everywhere. Your job is to turn those numbers into meaning.</p><p><b>The core specification sheet</b></p><p>&bull; Length: overall size in one dimension<br/>&bull; Beam: width<br/>&bull; Draft: depth below the waterline<br/>&bull; GT: enclosed volume<br/>&bull; Cruising speed: normal operating performance<br/>&bull; Maximum speed: upper published performance<br/>&bull; Range: travel capability under stated conditions<br/>&bull; Fuel capacity: fuel carried<br/>&bull; Guest capacity: accommodation or certification under the relevant arrangement<br/>&bull; Crew: crew accommodation and capacity<br/>&bull; Year built: delivery or construction date<br/>&bull; Refit: significant subsequent work<br/>&bull; Asking price: current advertised price</p><p><b>Year built is not the whole story</b></p><p>A 2008 yacht heavily refitted in 2025 is not the same proposition as an untouched 2008 yacht. A well-maintained older yacht can also compete differently from a newer one. So don't stop at \"how old is it?\" Ask: <em>what is its current condition, specification and market position?</em></p><p><b>Refit</b></p><p>A refit can range from cosmetic work to major technical and structural projects: paint, interiors, machinery, electronics, systems, cabins, exterior areas, structural work. Never assume \"refitted\" means \"as good as new.\" Ask what was actually done.</p><p><b>Cabins and crew</b></p><p>Don't simply count cabins. Look at their configuration. And don't simply count crew berths: crew numbers can influence service level, operating cost, accommodation, guest experience and maintenance capability.</p><p><b>The price</b></p><p>The asking price is important, but only a starting point for analysis. A yacht listed at €15 million is not automatically worth €15 million, not automatically going to sell for €15 million, and not automatically worth more or less than another yacht solely because of its asking price. You will study valuation properly in Module 3.</p><p><b>Turning numbers into meaning</b></p><p>Two hypothetical yachts:</p><p>&bull; Yacht A: 40m, 320 GT, 10 guests, 8 crew, 18 kn cruise, 2,500 nm range, 2.4m draft, €14m<br/>&bull; Yacht B: 40m, 470 GT, 10 guests, 9 crew, 14 kn cruise, 5,000 nm range, 2.9m draft, €15m</p><p>There is no automatic winner. If the client prioritises fast Mediterranean cruising and shallower anchorages, Yacht A may become more relevant. If the client prioritises long-range cruising and interior volume, Yacht B may become more relevant.</p><p>The specifications don't make the decision. They provide the evidence for the discussion.</p>", "q": "A 2008 yacht was heavily refitted in 2025. What should you do with that information?", "opts": ["Treat it as equivalent to a new build", "Ignore it, since age is what determines value", "Assume the refit covered all technical systems", "Ask what was actually done, because \"refitted\" doesn't automatically mean \"as good as new\""], "correct": 3}, {"heading": "Exercise: What Do the Numbers Say?", "body": "<p><b>From observation to interpretation</b></p><p>Return to the yacht you have been studying. Collect its actual specifications, then interpret them.</p><p>You are now moving from <b>observation → interpretation → investigation.</b> This replaces several separate comparison exercises.</p>", "exercise": {"intro": "Use the same yacht again. Collect its real specifications from the listing first.", "groups": [{"title": "Reading the numbers", "section": "yachts", "fields": [{"key": "n_yacht", "label": "Which yacht, and what are its key specs (length, beam, draft, GT, speeds, range, guests, crew, year, price)?", "type": "long", "min": 40}, {"key": "n_use", "label": "What do these numbers tell me about how this yacht is intended to be used?", "type": "long", "min": 40}]}, {"title": "Strength, compromise, question", "section": "yachts", "fields": [{"key": "n_strength", "label": "One strength suggested by the numbers", "type": "long", "min": 15}, {"key": "n_compromise", "label": "One potential compromise", "type": "long", "min": 15}, {"key": "n_question", "label": "One question that requires further investigation", "type": "long", "min": 15}]}]}}, {"heading": "Chapter 6: Your First Yacht Comparison", "body": "<p><b>Now we put everything together</b></p><p>You have learned to recognise major yacht types, read exterior design, understand basic layouts, recognise operational spaces, understand fundamental technical terms and read key specifications.</p><p>Now you are going to perform your first simplified broker comparison. This is not a valuation. It is not a survey. It is a training exercise in <b>client-specific recommendation.</b></p><p><b>The client</b></p><p>A couple in their early 50s, with two adult children and a young grandchild, substantial disposable income and no previous yacht ownership experience.</p><p>&bull; Budget: €10-14 million<br/>&bull; Cruising: France, Italy, Corsica, Sardinia, Greece<br/>&bull; Expected use: 8-10 weeks per year</p><p>They tell you:</p><p><em>\"We want a yacht that feels luxurious but not enormous. We want to spend most of our time outside. We love swimming, restaurants and exploring smaller coastal destinations. We don't want to spend our holidays feeling like we're managing a hotel.\"</em></p><p>They add:</p><p><em>\"We'd like to bring the family, but we don't want a yacht that requires a huge crew.\"</em></p><p><b>Yacht A: 38m motor yacht</b></p><p>&bull; 380 GT, 10 guests, 8 crew<br/>&bull; 17 kn cruise, 23 kn maximum, 2,000 nm range<br/>&bull; 2.2m draft, built 2018, refitted 2024, asking €12.5m</p><p>Potential strengths: shallow draft, strong exterior spaces, excellent swimming platform, modern interior, relatively compact crew requirement, good Mediterranean profile.</p><p>Potential compromises: shorter range, less interior volume, smaller technical spaces.</p><p><b>Yacht B: 42m motor yacht</b></p><p>&bull; 520 GT, 10 guests, 10 crew<br/>&bull; 14 kn cruise, 19 kn maximum, 4,500 nm range<br/>&bull; 2.8m draft, built 2015, refitted 2022, asking €13.5m</p><p>Potential strengths: much greater volume, excellent range, large interior, substantial crew facilities, strong long-range capability.</p><p>Potential compromises: deeper draft, larger crew requirement, less suited to shallow cruising, older refit.</p><p><b>Yacht C: 39m motor yacht</b></p><p>&bull; 410 GT, 10 guests, 9 crew<br/>&bull; 20 kn cruise, 27 kn maximum, 1,800 nm range<br/>&bull; 2.4m draft, built 2020, asking €14m</p><p>Potential strengths: newer, fast, modern styling, good Mediterranean access, strong performance.</p><p>Potential compromises: shorter range, less volume than Yacht B, highest asking price, performance may exceed the client's needs.</p>", "q": "Why is this comparison not a valuation or a survey?", "opts": ["Because the yachts are fictional and can't be compared", "It is a training exercise in recommending a yacht based on a specific client's needs", "Because valuations only apply to older yachts", "Because surveys are done by brokers, not surveyors"], "correct": 1}, {"heading": "Broker Challenge: Recommend a Yacht", "body": "<p><b>Your broker challenge</b></p><p>Work through the five steps on the next screen: the client's priorities, a comparison, a recommendation, and two twists in the client's story.</p><p>Do not write \"Yacht A is the best.\" Your recommendation must connect the yacht to the client's requirements.</p>", "exercise": {"intro": "Use the client brief and the three yachts from the previous page.", "groups": [{"title": "Step 1: the client's five priorities", "section": "services", "fields": [{"key": "p1", "label": "Priority 1", "type": "short", "min": 5}, {"key": "p2", "label": "Priority 2", "type": "short", "min": 5}, {"key": "p3", "label": "Priority 3", "type": "short", "min": 5}, {"key": "p4", "label": "Priority 4", "type": "short", "min": 5}, {"key": "p5", "label": "Priority 5", "type": "short", "min": 5}]}, {"title": "Step 2: best suited characteristic", "section": "services", "fields": [{"key": "best_a", "label": "Best suited characteristic: Yacht A", "type": "long", "min": 12}, {"key": "best_b", "label": "Best suited characteristic: Yacht B", "type": "long", "min": 12}, {"key": "best_c", "label": "Best suited characteristic: Yacht C", "type": "long", "min": 12}]}, {"title": "Step 2: biggest compromise", "section": "services", "fields": [{"key": "comp_a", "label": "Biggest compromise: Yacht A", "type": "long", "min": 12}, {"key": "comp_b", "label": "Biggest compromise: Yacht B", "type": "long", "min": 12}, {"key": "comp_c", "label": "Biggest compromise: Yacht C", "type": "long", "min": 12}]}, {"title": "Step 2: key question to investigate", "section": "services", "fields": [{"key": "ask_a", "label": "Key question to investigate: Yacht A", "type": "long", "min": 12}, {"key": "ask_b", "label": "Key question to investigate: Yacht B", "type": "long", "min": 12}, {"key": "ask_c", "label": "Key question to investigate: Yacht C", "type": "long", "min": 12}]}, {"title": "Step 3: my recommendation", "section": "services", "fields": [{"key": "recommend", "label": "Which yacht would you present first? Write about 150 words beginning: \"Based on what I know about the client...\"", "type": "long", "min": 400, "placeholder": "Based on what I know about the client..."}]}, {"title": "Step 4: change one variable", "section": "services", "fields": [{"key": "twist1", "label": "The client now says: \"We actually don't care about speed. We would rather spend three weeks cruising Greece and visiting places that are difficult to access with larger yachts.\" Would your recommendation change? Explain briefly.", "type": "long", "min": 40}]}, {"title": "Step 5: change another variable", "section": "services", "fields": [{"key": "twist2", "label": "The client then says: \"Our children are bringing friends. We may have ten guests regularly, and we really want a very high level of service.\" Which specifications become more important, and why?", "type": "long", "min": 40}]}]}}, {"heading": "Module 2 Glossary", "body": "<p><b>Make sure you can explain these terms simply</b></p><p>&bull; <b>Beam:</b> width of the yacht.<br/>&bull; <b>Bow:</b> forward end of the yacht.<br/>&bull; <b>Draft:</b> depth of the yacht below the waterline.<br/>&bull; <b>Gross Tonnage (GT):</b> a measure of enclosed vessel volume.<br/>&bull; <b>Displacement:</b> a measure related to the vessel's mass through the water it displaces.<br/>&bull; <b>Range:</b> distance a yacht can travel under stated operating assumptions before refuelling.<br/>&bull; <b>Cruising speed:</b> a normal operating speed under stated conditions.<br/>&bull; <b>Maximum speed:</b> the highest published speed under stated conditions.<br/>&bull; <b>Refit:</b> significant work undertaken to refurbish, upgrade or modify a yacht.<br/>&bull; <b>Tender:</b> a smaller boat used in connection with a larger yacht.<br/>&bull; <b>Guest capacity:</b> the number of guests a yacht is designed or certified to accommodate under the relevant arrangement.<br/>&bull; <b>Crew capacity:</b> the number of crew the yacht is designed to accommodate.</p>", "q": "Which pair of terms and meanings is correct?", "opts": ["Draft: width of the yacht. Beam: depth below the waterline", "Draft: enclosed volume. Beam: mass", "Draft: depth below the waterline. Beam: width of the yacht", "Draft: forward end of the yacht. Beam: range"], "correct": 2}, {"heading": "Exercise: The Yacht Observation Test", "body": "<p><b>Module 2 observation test</b></p><p>Choose one real yacht listing. Before reading the description, study its photographs. Then write three short lists: what you can see, what you can infer, and what you need to verify.</p><p>Then read the listing and specifications. What changed? This is the habit you want to develop: <b>observe → question → verify → interpret.</b></p>", "exercise": {"intro": "Pick a real listing you haven't used yet. Fill in the three lists before you read the description.", "groups": [{"title": "Before the listing", "section": "yachts", "fields": [{"key": "o_yacht", "label": "Which yacht?", "type": "short", "min": 3}, {"key": "o_see1", "label": "I can see (1)", "type": "short", "min": 5}, {"key": "o_see2", "label": "I can see (2)", "type": "short", "min": 5}, {"key": "o_see3", "label": "I can see (3)", "type": "short", "min": 5}, {"key": "o_inf1", "label": "I can infer (1)", "type": "short", "min": 5}, {"key": "o_inf2", "label": "I can infer (2)", "type": "short", "min": 5}, {"key": "o_inf3", "label": "I can infer (3)", "type": "short", "min": 5}, {"key": "o_ver1", "label": "I need to verify (1)", "type": "short", "min": 5}, {"key": "o_ver2", "label": "I need to verify (2)", "type": "short", "min": 5}, {"key": "o_ver3", "label": "I need to verify (3)", "type": "short", "min": 5}]}, {"title": "After the listing", "section": "yachts", "fields": [{"key": "o_changed", "label": "Now read the listing and specifications. What changed?", "type": "long", "min": 30}]}]}}, {"heading": "Broker's Notebook and Professional Output: The Yacht Comparison Sheet", "body": "<p><b>Broker's notebook</b></p><p>You should now be able to look at a yacht and begin describing it in professional terms. Not perfectly. Not comprehensively. But intelligently. You should understand that:</p><p>&bull; yachts are designed around different purposes<br/>&bull; exterior design can reveal intended use<br/>&bull; interior layout affects lifestyle and operation<br/>&bull; crew areas are part of the yacht's functionality<br/>&bull; technical systems support the luxury experience<br/>&bull; specifications describe different aspects of the yacht<br/>&bull; age alone does not determine condition or value<br/>&bull; asking price is only one piece of the market picture<br/>&bull; the same yacht can suit one client and fail another</p><p>The bigger lesson:</p><p><em>A broker doesn't simply know yachts. A broker learns how to interpret yachts for people.</em></p><p><b>Professional output: the Yacht Comparison Sheet</b></p><p>Create a two-page comparison of two real yachts. Page 1 is the facts. Page 2 is the broker's view.</p><p>This becomes the second piece of your <b>Broker Portfolio.</b></p>", "exercise": {"intro": "Compare two real yachts. Page 1 is the facts (write values separated by commas). Page 2 is your broker's view of both.", "groups": [{"title": "Page 1: Yacht 1 facts", "section": "yachts", "fields": [{"key": "a_id", "label": "Name, builder, year", "type": "short", "min": 8}, {"key": "a_dims", "label": "Length, beam, draft, GT", "type": "short", "min": 8}, {"key": "a_perf", "label": "Cruising speed, maximum speed, range", "type": "short", "min": 8}, {"key": "a_acc", "label": "Guest capacity, crew, cabins", "type": "short", "min": 6}, {"key": "a_com", "label": "Asking price and refit history", "type": "short", "min": 8}]}, {"title": "Page 1: Yacht 2 facts", "section": "yachts", "fields": [{"key": "b_id", "label": "Name, builder, year", "type": "short", "min": 8}, {"key": "b_dims", "label": "Length, beam, draft, GT", "type": "short", "min": 8}, {"key": "b_perf", "label": "Cruising speed, maximum speed, range", "type": "short", "min": 8}, {"key": "b_acc", "label": "Guest capacity, crew, cabins", "type": "short", "min": 6}, {"key": "b_com", "label": "Asking price and refit history", "type": "short", "min": 8}]}, {"title": "Page 2: the broker's view", "section": "yachts", "fields": [{"key": "v_for", "label": "Who is each yacht for?", "type": "long", "min": 30}, {"key": "v_strong", "label": "What is each yacht's strongest characteristic?", "type": "long", "min": 30}, {"key": "v_comp", "label": "What is each yacht's biggest compromise?", "type": "long", "min": 30}, {"key": "v_notfit", "label": "Who might not be a good fit for each?", "type": "long", "min": 30}, {"key": "v_investigate", "label": "What would I investigate further?", "type": "long", "min": 30}, {"key": "v_lbroker", "label": "What would I ask the listing broker?", "type": "long", "min": 30}, {"key": "v_client", "label": "What would I ask the client?", "type": "long", "min": 30}]}]}}, {"heading": "Final Reflection", "body": "<p><b>Module 2 final reflection</b></p><p>You have studied yachts closely. Now write down what that has changed for you. Your answers go to your Broker Portfolio.</p>", "exercise": {"intro": "Answer honestly. Nobody is marking your enthusiasm.", "groups": [{"title": "What I noticed", "section": "profile", "fields": [{"key": "r_feature", "label": "The yacht feature I find most interesting is...", "type": "short", "min": 8}, {"key": "r_tech", "label": "The technical subject I most want to understand better is...", "type": "short", "min": 8}, {"key": "r_never", "label": "The part of yacht design I had never considered before is...", "type": "short", "min": 8}, {"key": "r_surprise", "label": "I was surprised by...", "type": "short", "min": 8}, {"key": "r_notice", "label": "When I look at a yacht now, I notice...", "type": "short", "min": 8}]}, {"title": "Yacht types", "section": "market", "fields": [{"key": "r_most", "label": "The yacht type I am currently most curious about is...", "type": "short", "min": 3}, {"key": "r_least", "label": "The yacht type I am currently least interested in is...", "type": "short", "min": 3}]}, {"title": "The honest question", "section": "profile", "fields": [{"key": "r_curious", "label": "After actually studying yachts, am I more or less curious about working in this industry? Why?", "type": "long", "min": 40}]}]}}, {"heading": "Final Broker Challenge and What Comes Next", "body": "<p><b>Final broker challenge</b></p><p>You are standing on the dock with a prospective client. Three yachts are visible. The client points toward them and asks:</p><p><em>\"Which one would you buy?\"</em></p><p>You now know that the useful answer is not immediate. You need to understand what they want to do, where they want to go, who will be onboard, how they will use the yacht and what compromises they are willing to make.</p><p>That is the shift from <b>looking at yachts</b> to <b>interpreting yachts.</b></p><p>You have started learning the language. You have started understanding the architecture. You have started reading the numbers. And you have made your first client-specific recommendation.</p><p>You are not a yacht broker yet. But you have begun to think like one.</p><p><b>What comes next</b></p><p>You now know what a yacht is. The next question is harder:</p><p><em>What is it actually worth?</em></p><p>Why can one 40-metre yacht be worth €10 million while another can be worth €20 million? Why can a newer yacht sometimes be worth less than an older one? Why does the builder matter? Why does condition matter? Why can a refit change the conversation?</p><p>That is where we go next: <b>Module 3, The Yacht Market.</b> <em>How does this business actually work?</em></p><p>Now we stop looking at yachts as individual objects. We start looking at them as <b>marketable assets.</b></p>", "q": "What is the central shift this module is trying to create?", "opts": ["From studying yachts to memorising every specification", "From brokerage to yacht management", "From observing yachts to certifying them", "From looking at yachts to interpreting yachts for the people who might buy them"], "correct": 3}]$json$;
  v_final jsonb := $json$[{"q": "Why can two yachts of the same length feel completely different?", "opts": ["Length is irrelevant", "Beam, volume, layout, design, machinery and configuration can differ substantially", "One must be older", "They must have different engines"], "correct": 1}, {"q": "What should you consider when identifying a yacht type?", "opts": ["Price alone", "Engine size alone", "Number of bedrooms alone", "Intended use, operating environment and design priorities"], "correct": 3}, {"q": "What does GT broadly describe?", "opts": ["Yacht weight", "Engine power", "Enclosed vessel volume", "Fuel consumption"], "correct": 2}, {"q": "Why does draft matter?", "opts": ["It can affect access to shallow waters", "It determines price", "It determines crew size", "It determines cabin numbers"], "correct": 0}, {"q": "Why is maximum speed not enough to understand performance?", "opts": ["Maximum speed is never useful", "Speed has no relationship to yacht design", "Maximum speed is always incorrect", "Cruising speed, range, consumption and intended use may matter more"], "correct": 3}, {"q": "What is the purpose of a yacht comparison?", "opts": ["To identify the universally best yacht", "To assess suitability for a particular client and intended use", "To prove technical expertise", "To negotiate a lower price"], "correct": 1}, {"q": "What is the difference between observation and verification?", "opts": ["They are the same", "Observation is more valuable than research", "Observation creates questions; verification establishes what is actually known", "Verification is only necessary for engineers"], "correct": 2}]$json$;
begin
  select id into v_module from public.academy_modules where track = 'yachts' and module_number = 2;
  if v_module is null then
    raise exception 'Yachts module 2 not found';
  end if;

  update public.academy_modules
     set title = 'Meet the Yacht', description = 'Do I actually find yachts interesting?'
   where id = v_module;

  delete from public.academy_module_pages where module_id = v_module;
  delete from public.academy_quiz_questions where module_id = v_module;

  for rec in select * from jsonb_array_elements(v_pages) loop
    n := n + 1;
    if rec ? 'exercise' then
      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id, exercise)
      values (v_module, n, rec->>'heading', rec->>'body', null, rec->'exercise');
    else
      insert into public.academy_quiz_questions (module_id, question_text, order_index, stage, page_number)
      values (v_module, rec->>'q', 0, 'checkpoint', n)
      returning id into v_q;

      for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
        insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
        values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
      end loop;

      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id)
      values (v_module, n, rec->>'heading', rec->>'body', v_q);
    end if;
  end loop;

  n := 0;
  for rec in select * from jsonb_array_elements(v_final) loop
    n := n + 1;
    insert into public.academy_quiz_questions (module_id, question_text, order_index, stage)
    values (v_module, rec->>'q', n - 1, 'final')
    returning id into v_q;

    for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
      insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
      values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
    end loop;
  end loop;
end
$mig$;
